					return ea - eb || a.name.localeCompare( b.name );
				} ).forEach( function ( v ) {
					var opt = el( 'option', '', v.name + ' (' + v.lang + ')' );
					opt.value = v.name;
					vsel.appendChild( opt );
				} );
				vsel.value = s.voice && vs.some( function ( v ) { return v.name === s.voice; } ) ? s.voice : vsel.options[ 0 ].value;
				vsel.setAttribute( 'aria-label', 'Voice' );
				vsel.addEventListener( 'change', function () {
					var st = loadAlerts();
					st.voice = vsel.value;
					saveAlerts( st );
					chime( 5 );
				} );
				row3.appendChild( vsel );
			}
			panel.appendChild( row3 );
		}
		var vol = el( 'input', 'wnx-vol' );
		vol.type = 'range';
		vol.min = 0;
		vol.max = 1;
		vol.step = 0.05;
		vol.value = s.vol === undefined ? 0.6 : s.vol;
		vol.setAttribute( 'aria-label', 'Volume' );
		vol.addEventListener( 'change', function () {
			var st = loadAlerts();
			st.vol = +vol.value;
			saveAlerts( st );
			chime( 5 );
		} );
		panel.appendChild( vol );
		var tests = el( 'div', 'wnx-tests' );
		[ [ 15, 'Test 15' ], [ 5, 'Test 5' ], [ 0, 'Test spawn' ] ].forEach( function ( t ) {
			var b = el( 'button', '', t[ 1 ] );
			b.type = 'button';
			b.addEventListener( 'click', function () { chime( t[ 0 ] ); refreshAll(); } );
			tests.appendChild( b );
		} );
		panel.appendChild( tests );
		panel.appendChild( grid );
		var bar = document.getElementById( 'wnx-barhost' );
		if ( bar && bar.contains( stack ) ) {
			var lab = el( 'label', 'wnx-showbar' );
			var sb = el( 'input' );
			sb.type = 'checkbox';
			sb.checked = s.bar !== false;
			sb.addEventListener( 'change', function () {
				var st = loadAlerts();
				st.bar = sb.checked;
				saveAlerts( st );
				applyBar();
			} );
			lab.appendChild( sb );
			lab.appendChild( document.createTextNode( ' Show the timers in the header' ) );
			panel.appendChild( lab );
		}
		panel.appendChild( el( 'div', 'wnx-hint', 'Plays a sound while this wiki page is open in a browser tab. Saved on this device only.' ) );
	}
	function applyBar() {
		var bar = document.getElementById( 'wnx-barhost' );
		if ( bar ) { bar.classList.toggle( 'wnx-bar-min', loadAlerts().bar === false ); }
	}
	function refreshAll() {
		applyBar();
		roots.forEach( function ( r ) { if ( r.classList.contains( 'wnx-stack' ) ) { refreshBell( r ); } } );
	}
	function initAlerts( stack ) {
		var wrap = el( 'div', 'wnx-alerts' );
		var btn = el( 'button', 'wnx-bell', '' );
		btn.type = 'button';
		var panel = el( 'div', 'wnx-panel' );
		panel.hidden = true;
		btn.addEventListener( 'click', function () {
			audio();
			if ( panel.hidden ) { buildPanel( stack, panel ); }
			panel.hidden = !panel.hidden;
			btn.setAttribute( 'aria-expanded', String( !panel.hidden ) );
			setTimeout( refreshAll, 100 );
		} );
		wrap.appendChild( panel );
		wrap.appendChild( btn );
		var bar = document.getElementById( 'wnx-barhost' );
		( bar && bar.contains( stack ) ? ( bar.querySelector( '.wnx-alertshost' ) || bar ) : stack ).appendChild( wrap );
		stack.wnxBell = btn;
		refreshBell( stack );
	}
	document.addEventListener( 'click', function () {
		if ( anyAlert( loadAlerts() ) ) { audio(); setTimeout( refreshAll, 100 ); }
	} );

	// ---- the weekly Activity Token boxes ({{WeeklyTokens}}): highlight the active day, count down to the next one
	function renderWeekly( root ) {
		var now = Date.now();
		var zone = root.getAttribute( 'data-zone' ) || SERVER;
		var p = parts( now, zone );
		var midnight = toUtc( p.y, p.mo, p.d + 1, 0, 0, zone );
		var activeBox = null;
		var tomorrow = null;
		var soonest = null;
		Array.prototype.forEach.call( root.querySelectorAll( '.wkq-day' ), function ( box ) {
			var dow = +box.getAttribute( 'data-dow' );
			var state = box.querySelector( '.wkq-state' );
			var start = toUtc( p.y, p.mo, p.d + ( dow - p.wi + 7 ) % 7, 0, 0, zone );
			box.wkqStart = start;
			if ( dow === p.wi ) {
				activeBox = box;
				setCls( box, 'wkq-active', true );
				setText( state, 'Active now \u00B7 ends ' + leftText( midnight, now ) );
			} else {
				setCls( box, 'wkq-active', false );
				setText( state, 'Starts ' + leftText( start, now ) );
				if ( !soonest || start < soonest.wkqStart ) { soonest = box; }
			}
			if ( dow === ( p.wi + 1 ) % 7 ) { tomorrow = box; }
		} );
		var next = root.querySelector( '.wkq-next' );
		var target;
		// the small hero version has room for fewer words
		var mini = root.classList.contains( 'wkq-mini' );
		function dayWordW( box ) { return mini ? box.getAttribute( 'data-name' ).slice( 0, 3 ) : box.getAttribute( 'data-name' ); }
		if ( activeBox && tomorrow ) {
			target = midnight;
			setText( next, dayWordW( tomorrow ) + ( mini ? ' ' : ' begins ' ) + leftText( midnight, now ) );
		} else if ( activeBox ) {
			target = midnight;
			setText( next, ( mini ? 'Ends ' : 'The weekly quests end ' ) + leftText( midnight, now ) );
		} else if ( soonest ) {
			target = soonest.wkqStart;
			setText( next, dayWordW( soonest ) + ( mini ? ' ' : ' begins ' ) + leftText( target, now ) );
		}
		if ( target ) {
			var rem = ( target - now ) % 60000;
			root.wnxDelay = rem > 0 ? rem : 60000;
		}
	}

	function render( root ) {
		if ( root.classList.contains( 'wnx-stack' ) ) { renderNext( root ); } else if ( root.classList.contains( 'wkq' ) ) { renderWeekly( root ); } else { renderTable( root ); }
	}

	function renderAll() {
		roots.forEach( render );
	}

	// ONE timer for everything on the page: it sleeps until the next thing that matters (a countdown that changes its
	// words, or an alert that is due) and at most 30 seconds, and a hidden tab only keeps the alerts alive.
	var wakeTimer = null;
	var renderDue = 0;

	function staleStack( r ) {
		var now = Date.now();
		var stale = false;
		Array.prototype.forEach.call( r.querySelectorAll( '.wnx' ), function ( row ) {
			Object.keys( row.wnxBy || {} ).forEach( function ( id ) { if ( row.wnxBy[ id ] < now ) { stale = true; } } );
		} );
		return stale;
	}

	function wake() {
		clearTimeout( wakeTimer );
		var now = Date.now();
		alertTick();
		if ( !document.hidden ) {
			if ( now >= renderDue ) {
				renderAll();
				var d = 60000 - now % 60000;
				roots.forEach( function ( r ) { if ( r.wnxDelay ) { d = Math.min( d, r.wnxDelay ); } } );
				renderDue = now + d + 80;
			}
		} else if ( anyAlert( loadAlerts() ) ) {
			// nobody is looking, but the spawn times behind the alerts must not go stale
			roots.forEach( function ( r ) { if ( r.classList.contains( 'wnx-stack' ) && staleStack( r ) ) { renderNext( r ); } } );
		}
		var next = alertTick();
		var wait = 30000;
		if ( !document.hidden ) { wait = Math.min( wait, renderDue - Date.now() ); }
		wait = Math.min( wait, next - Date.now() );
		wakeTimer = setTimeout( wake, Math.max( 500, wait ) + 50 );
	}
	function replan() {
		clearTimeout( wakeTimer );
		wakeTimer = setTimeout( wake, 0 );
	}
	document.addEventListener( 'visibilitychange', function () {
		if ( !document.hidden ) { renderDue = 0; }
		replan();
	} );

	function init( root ) {
		if ( root.wevReady ) { return; }
		root.wevReady = true;
		root.classList.add( 'wev-js' );
		var tz = root.querySelector( '.wev-tz' );
		if ( tz ) {
			var sel = el( 'select', 'wev-tzsel' );
			[ [ 'device', 'My time zone' ], [ 'server', 'Server time' ], [ 'utc', 'UTC' ] ].forEach( function ( o ) {
				var opt = el( 'option', '', o[ 1 ] );
				opt.value = o[ 0 ];
				sel.appendChild( opt );
			} );
			sel.addEventListener( 'change', function () {
				try {
					mw.storage.set( 'wbt-zone', sel.value );
				} catch ( e ) {}
				renderAll();
			} );
			tz.appendChild( sel );
		}
		root.addEventListener( 'click', function ( e ) {
			var h = e.target.closest ? e.target.closest( '.wev-dayhead' ) : null;
			if ( h && h.parentNode ) { h.parentNode.classList.toggle( 'wev-open' ); }
		} );
		roots.push( root );
		if ( root.classList.contains( 'wnx-stack' ) ) { initAlerts( root ); }
		render( root );
		renderDue = 0;
		replan();
	}


	// ---- the timer bar in the header: loaded on every page so the sound alerts work wherever you are
	var BAR_SRC = '{{WorldNext|type=boss,daily,game,trader}}';
	var BAR_CACHE = 'wnx-bar-html-v4';

	function getBarHtml( done ) {
		try {
			var c = JSON.parse( mw.storage.get( BAR_CACHE ) || 'null' );
			if ( c && c.h && Date.now() - c.t < 60000 ) { done( c.h ); return; }
		} catch ( e ) {}
		mw.loader.using( 'mediawiki.api' ).then( function () {
			return new mw.Api().get( { action: 'parse', text: BAR_SRC, contentmodel: 'wikitext', prop: 'text', disablelimitreport: 1, formatversion: 2 } );
		} ).then( function ( r ) {
			var h = r && r.parse && r.parse.text;
			if ( !h ) { return; }
			try { mw.storage.set( BAR_CACHE, JSON.stringify( { t: Date.now(), h: h } ) ); } catch ( e ) {}
			done( h );
		} );
	}

	function mountBar() {
		if ( document.getElementById( 'wnx-barhost' ) ) { return; }
		var slot = document.querySelector( '.citizen-header' );
		if ( !slot ) { return; }
		var host = el( 'div', 'wnx-bar' );
		host.id = 'wnx-barhost';
		slot.appendChild( host );
		document.documentElement.classList.add( 'wnx-has-bar' );
		getBarHtml( function ( h ) {
			var d = el( 'div', 'wnx-barsrc' );
			d.innerHTML = h;
			host.insertBefore( d, host.firstChild );
			// the bell lives in its own parser-output box so the template styles reach it
			var ah = el( 'div', 'mw-parser-output wnx-alertshost' );
			host.appendChild( ah );
			var st = d.querySelector( '.wnx-stack' );
			if ( st ) { init( st ); }
			applyBar();
		} );
	}

	$( mountBar );

	mw.hook( 'wikipage.content' ).add( function ( $content ) {
		$content.find( '.wev, .wnx-stack, .wkq' ).each( function () {
			init( this );
		} );
	} );
}() );
